const G=Growth,KEY='ieum-demo-v1';let db;try{db=JSON.parse(localStorage.getItem(KEY));if(db?.version!==1)db=G.seed()}catch{db=G.seed()}let role='원장',teacher='김서연',page='dashboard',selected=new Set(),className='Bridge A',studentId=1,month='2026-09',filters={},search='',tab='전체';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),S=id=>db.students.find(s=>s.id===Number(id)),actor=()=>role==='교사'?teacher:role==='조교'?'조교 이지은':'원장';
const menus=[['dashboard','◫','학원 상황판'],['home','⌂','오늘의 수업 준비'],['session','▤','수업 기록'],['board','▦','출근 브리핑 · 학습실'],['students','♧','학생 360'],['cases','◎','Learning Case'],['reports','▧','월말리포트'],['notifications','♧','학부모 알림'],['settings','⚙','설정']];
function allowed(){return role==='원장'?menus:menus.filter(m=>(role==='교사'?['home','session','students','cases','reports','notifications']:['board']).includes(m[0]))}
function scope(){return db.students.filter(s=>role!=='교사'||s.teacher===teacher||s.native===teacher)}
let savedState=JSON.stringify(db),saveFailed=false,retrySave=null;
// Restore only application state on failure; leave the user's input controls intact.
function save(retry=null){
  try{const candidate=JSON.stringify(db);localStorage.setItem(KEY,candidate);savedState=candidate;const recovered=saveFailed;saveFailed=false;retrySave=null;if(recovered)toast('저장했습니다.');return true;}
  catch{db=JSON.parse(savedState);saveFailed=true;retrySave=retry;toast('저장하지 못했습니다. 입력을 유지했습니다. 다시 저장해 주세요.',true);return false;}
}
function observationOptions(values,value){return `<option value="" ${!value?'selected':''}>미확인</option>`+options(values,value);}

function toast(t,persistent=false){$('toast').textContent=t;if(persistent&&retrySave)$('toast').innerHTML=esc(t)+' <button class="small" data-action="retry-save">다시 저장</button>';$('toast').style.display='block';clearTimeout(window.toastTimer);if(!persistent)window.toastTimer=setTimeout(()=>$('toast').style.display='none',3200)}
function uiText(v){return String(v??'').replace(/Primary/g,'기본 과제').replace(/Secondary/g,'추가 과제').replace(/\bOPEN\b/g,'미해결');}
function badge(t,c=''){return `<span class="badge ${c}">${esc(uiText(t))}</span>`}function link(s){return `<button class="student-link" data-action="student" data-id="${s.id}">${esc(s.name)}</button>`}function avatar(s){return `<span class="avatar">${s.name.slice(1)}</span>`}function options(a,v){return a.map(x=>`<option value="${esc(x)}" ${x===v?'selected':''}>${esc(uiText(x))}</option>`).join('')}
function filtered(){return scope().filter(s=>(!search||`${s.name} ${s.school} ${s.class}`.includes(search))&&['teacher','class','school','grade'].every(k=>!filters[k]||s[k]===filters[k]||(k==='teacher'&&s.native===filters[k])))}
function evs(ids){return db.events.filter(e=>ids.includes(e.student)&&(!filters.from||e.date.slice(0,10)>=filters.from)&&(!filters.to||e.date.slice(0,10)<=filters.to)&&(!filters.type||e.type===filters.type))}
function filterBar(){return `<div class="filters"><input id="search" aria-label="학생 검색" placeholder="학생 이름 검색" value="${esc(search)}">${[['teacher','교사'],['class','반'],['school','학교'],['grade','학년']].map(([k,t])=>`<select data-filter="${k}" aria-label="${t}"><option value="">전체 ${t}</option>${options([...new Set(scope().flatMap(s=>k==='teacher'?[s.teacher,s.native]:[s[k]]))],filters[k])}</select>`).join('')}<button class="small" data-action="clear-filters">초기화</button></div>`}
function heading(title,subtitle,action=''){return `<div class="heading"><div class="eyebrow">${role==='원장'?'DIRECTOR WORKSPACE':role==='교사'?'TEACHER WORKSPACE':'LEARNING ROOM'}</div><div class="row between"><div><h1>${title}</h1><span class="muted">${subtitle}</span></div>${action}</div></div>`}
function navIcon(id){const paths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',session:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',board:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16M15 4v16"/>',students:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>',cases:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',reports:'<path d="M5 3h10l4 4v14H5ZM14 3v5h5M9 12h6M9 16h6"/>',notifications:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5ZM10 21h4"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="15" cy="17" r="3" fill="currentColor" stroke="none"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[id]||paths.dashboard}</svg>`;}
function render(){if(!allowed().some(m=>m[0]===page))page=allowed()[0][0];$('app').innerHTML=`<div class="layout" data-view="${page}"><aside class="sidebar"><div class="brand"><b>이</b>이음<small>GROWTH TOGETHER</small></div><div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="주요 메뉴">${allowed().map(([id,i,t])=>`<button data-page="${id}" ${page===id?'aria-current="page"':''} class="${page===id?'active':''}"><span class="icon">${navIcon(id)}</span>${t}</button>`).join('')}</nav></div><div class="sidebar-bottom"><span class="eyebrow">OUR PURPOSE</span><b>기록이 쌓이면<br>성장이 보입니다.</b><p>발견부터 변화까지,<br>학생의 배움을 이어주세요.</p>${badge('체험용 워크스페이스')}</div></aside><main><header class="topbar"><div class="crumb">이음 영어학원 <span style="margin:0 12px">/</span> ${menus.find(m=>m[0]===page)?.[2]}</div><div class="row"><span class="note">2026.10.01 목요일 · 데모 기준일</span><select id="role" aria-label="체험 역할">${options(['원장','교사','조교'],role)}</select>${role==='교사'?`<select id="teacher" aria-label="교사 선택">${options(['김서연','박지훈','이수진','James'],teacher)}</select>`:''}<span class="avatar">${role==='원장'?'원장':role==='조교'?'조교':teacher.slice(0,1)}</span></div></header><div class="content"><div class="demo"><span class="demo-dot"></span><b>체험 모드</b><span>가상 데이터 · 이 브라우저에 저장 · 실제 발송 없음</span></div>${({dashboard,home,session,board,students,cases,reports,notifications,settings})[page]()}</div></main></div>`;}
function stats(list){return `<div class="stats">${list.map(([t,n,u,h])=>`<div class="stat"><div class="row between"><span class="muted">${t}</span></div><div class="value">${n}<small>${u}</small></div><div class="hint">${h}</div></div>`).join('')}</div>`}
function analytics(ids,es){
const tasks=db.tasks.filter(t=>ids.includes(t.student)),done=tasks.filter(t=>!t.open).length,pct=tasks.length?Math.round(done/tasks.length*100):0;
const days=[...new Set(es.map(e=>e.date.slice(0,10)))].sort();const series=days.map(day=>es.filter(e=>e.date.startsWith(day)).length),max=Math.max(1,...series),points=series.map((n,i)=>`${24+i*312/Math.max(1,series.length-1)},${112-n/max*84}`),line=points.join(' ');
const cs=db.cases.filter(c=>ids.includes(c.student)),intervened=cs.filter(c=>c.intervention!=='담당교사 확인 예정'),improved=cs.filter(c=>['IMPROVING','CLOSED'].includes(c.status));
return `<div class="analytics"><section class="panel"><h2>과제 마무리 현황 · 현재</h2><div class="ring-wrap"><div class="ring"><svg viewBox="0 0 120 120" role="img" aria-label="과제 완료율 ${pct}%"><circle cx="60" cy="60" r="48" fill="none" stroke="#e3e9f2" stroke-width="10"/><circle cx="60" cy="60" r="48" fill="none" stroke="#0066cc" stroke-width="10" stroke-linecap="round" stroke-dasharray="${pct*3.016} 301.6"/></svg><div class="ring-center"><b>${pct}%</b><small>필수 과제 완료</small></div></div><div class="legend"><div><i class="dot"></i>완료 ${done}</div><div><i class="dot light"></i>진행·이월 ${tasks.length-done}</div></div></div><div class="formula">완료 ${done} ÷ 전체 ${tasks.length} × 100</div></section><section class="panel"><div class="row between"><h2>기록이 쌓이는 흐름 · 선택 기간</h2>${badge(es.length+'건')}</div>${days.length?`<svg class="trend" viewBox="0 0 360 140" role="img" aria-label="날짜별 학습 기록 건수"><path d="M24 28H340 M24 70H340 M24 112H340" stroke="#e3e3e8" stroke-dasharray="3 4"/><polygon points="24,112 ${line} ${24+(series.length-1)*312/Math.max(1,series.length-1)},112" fill="#dbe9fc" opacity=".75"/><polyline points="${line}" stroke="#0066cc" fill="none" stroke-width="2.5" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${p.split(',')[0]}" cy="${p.split(',')[1]}" r="4" fill="#0066cc" stroke="white" stroke-width="2"><title>${days[i]} · ${series[i]}건</title></circle><text x="${p.split(',')[0]}" y="${Number(p.split(',')[1])-10}" text-anchor="middle" font-size="12" fill="#626269">${series[i]}</text>`).join('')}</svg><div class="axis-labels"><span>${days[0]}</span><span>${days[days.length-1]}</span></div>`:'<div class="empty">선택 기간에 기록이 없습니다.</div>'}<div class="formula">기록이 있는 날짜별 건수 · 성적 추이가 아닙니다</div></section><section class="panel"><h2>관리의 흐름 · 현재</h2><div class="flow"><div class="flow-node"><span>발견</span><b>${cs.length}</b><span>전체 Case</span></div><span class="flow-arrow">→</span><div class="flow-node"><span>개입</span><b>${intervened.length}</b><span>지도 계획</span></div><span class="flow-arrow">→</span><div class="flow-node"><span>변화</span><b>${improved.length}</b><span>개선·종료</span></div></div><div class="mini-summary">현재 Case 상태를 집계합니다.<br>학생을 선택하면 변화의 근거를 볼 수 있어요.</div></section></div>`;
}
// Explicit demo scenarios; operational actions persist through the existing save transaction.
function careScenarios(){return [
 {id:1,kind:'신입 적응',since:'9/20 등록 · 12일차',reason:'첫 적응 상담 전 · 숙제 시작에 어려움',next:'오늘 수업 후 적응 여부 확인',due:'10/01',state:'확인 전'},
 {id:17,kind:'재원 관심',since:'9/28 보호자 상담',reason:'수업 부담을 이야기함 · 후속 상담 기한 경과',next:'보호자에게 학습량 조정 결과 확인',due:'9/30',state:'확인 전'},
 {id:33,kind:'재원 관심',since:'9/30 담임 관찰',reason:'참여가 줄어듦 · 수업에서 어려운 점 확인 필요',next:'다음 수업 전 짧은 개별 대화',due:'10/02',state:'교사 확인 중'},
 {id:9,kind:'신입 적응',since:'9/25 등록 · 7일차',reason:'친구와 활동 참여 · 첫 과제 수행 확인',next:'2주차 적응 상담',due:'10/08',state:'교사 확인 중'},
 {id:25,kind:'신입 적응',since:'9/18 등록 · 14일차',reason:'첫 상담 완료 · 수업 참여 안정적',next:'다음 정기 상담에서 경과 확인',due:'10/15',state:'확인 완료'}
 ].filter(x=>S(x.id)).map(x=>({...x,...db.experience?.care?.[x.id]}));}
function careRows(list){return list.map(x=>{const s=S(x.id);return `<div class="care-row"><span class="care-symbol ${x.kind==='신입 적응'?'new':'attention'}">${x.kind==='신입 적응'?'+':'!'}</span><div class="grow"><div class="row wrap">${link(s)}${badge(x.kind,'gray')}${badge(x.state,x.state==='확인 전'?'warn':'')}</div><p>${esc(x.reason)}</p><small>${esc(s.class)} · ${esc(s.teacher)} · 다음 확인 ${x.due}</small></div><button class="small" data-action="care-detail" data-id="${x.id}">확인하기 →</button></div>`}).join('')||'<div class="empty">현재 조건에 해당하는 확인 항목이 없습니다.</div>';}
function directorOverview(){const list=careScenarios().filter(x=>filtered().some(s=>s.id===x.id)),waiting=list.filter(x=>x.state==='확인 전'),newcomers=list.filter(x=>x.kind==='신입 적응');return heading('원장님, 반가워요.','오늘도 아이들의 작은 변화를 함께 살펴봐요.',`<span class="updated">데모 기준 10월 1일 · 화면 갱신 ${new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}</span>`)
 +`<div class="overview-colors" aria-label="학생 확인 업무 현황"><section class="overview-tile attention"><h2>먼저 확인할 학생</h2><strong>${waiting.length}<small>명</small></strong><p>확인 전 · 담당교사와 챙겨주세요</p></section><section class="overview-tile progressing"><h2>교사 확인 중</h2><strong>${list.filter(x=>x.state==='교사 확인 중').length}<small>명</small></strong><p>후속 확인을 진행하고 있어요</p></section><section class="overview-tile newcomer"><h2>신입생 적응</h2><strong>${newcomers.length}<small>명</small></strong><p>등록 이후 적응 경과를 살펴보세요</p></section><section class="overview-tile finished"><h2>후속 확인 완료</h2><strong>${list.filter(x=>x.state==='확인 완료').length}<small>명</small></strong><p>학생 문제 해결 판정과는 별개예요</p></section></div><p class="note">신입생 적응 인원은 다른 상태와 중복될 수 있습니다. 적응·재원 관심·등록/퇴원은 UI 체험용 가상 상황입니다. 퇴원 예측이나 근무 태도 평가가 아닙니다.</p>
 <div class="grid"><section class="panel"><div class="section-heading"><h2>놓치기 전에 챙길 학생</h2>${badge(waiting.length+'명 확인 전','warn')}</div>${careRows(list.filter(x=>x.kind==='재원 관심'||x.state==='확인 전'))}</section><section class="panel"><div class="section-heading"><h2>신입생 적응 여정</h2>${badge(newcomers.length+'명','gray')}</div><div class="journey"><span>등록</span><i>→</i><span>첫 주 관찰</span><i>→</i><span>적응 상담</span></div>${newcomers.map(x=>`<div class="item"><div class="grow">${link(S(x.id))}<p>${x.since} · ${x.state}</p></div><button class="small" data-action="care-detail" data-id="${x.id}">경과 보기</button></div>`).join('')||'<p class="note">해당 신입생 없음</p>'}</section></div>
 <div class="grid"><section class="panel"><div class="section-heading"><h2>재원 유지 · 9월 가상 예시</h2><button class="small" data-action="enrollment">내역 보기 →</button></div><div class="retention-equation"><span><b>46</b>월초</span><i>＋</i><span class="positive"><b>4</b>등록</span><i>−</i><span><b>2</b>퇴원</span><i>＝</i><span><b>48</b>월말</span></div><p class="note">전체 학원 예시 · 학생 필터와 무관한 고정 시나리오</p></section><section class="panel"><h2>교사별 후속 관리</h2><p class="note">현재 학생 필터 적용 · 관찰 횟수가 아닌 확인 업무 현황입니다.</p>${['김서연','박지훈','이수진'].map(name=>{const own=list.filter(x=>S(x.id).teacher===name),done=own.filter(x=>x.state!=='확인 전').length;return `<div class="teacher-progress"><b>${name}</b><div class="progress"><span style="width:${own.length?done/own.length*100:0}%"></span></div><span>${done}/${own.length} 착수·확인</span><button class="small" data-action="teacher-care" data-name="${name}">내역</button></div>`}).join('')}<p class="note">출퇴근·근무 태도 데이터는 아직 연결되지 않았습니다.</p></section></div>`;}
function teacherOverview(){const list=careScenarios().filter(x=>scope().some(s=>s.id===x.id));return `<div class="workspace-banner"><div><span class="eyebrow">BEFORE YOUR CLASS</span><h2>오늘 챙길 학생부터, 기록은 짧게.</h2><p>수업 준비 → 학생별 기록 → 상담 준비로 이어집니다.</p></div><button class="primary" data-page="session">빠른 수업 기록 →</button></div><div class="grid"><section class="panel"><h2>놓치지 않을 후속 확인</h2><p class="note">가상 적응·재원 관심 알림 · 확인 상태는 원장 화면과 공유됩니다.</p>${careRows(list)}</section><section class="panel consultation-card"><span class="eyebrow">PARENT CONVERSATION</span><h2>“이 학생, 무슨 이야기를 할까요?”</h2><p>잘한 점, 어려움, 학원의 대응을<br>학생 기록에서 모아 상담을 준비하세요.</p><label>상담할 학생<select id="consultStudent">${scope().map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.class)}</option>`).join('')}</select></label><button class="primary full-width" data-action="consult">상담 초안과 근거 보기 →</button><p class="note">기록 분류 기반 초안 · AI 분석 연결 전</p></section></div>`;}
function careDetail(id){const x=careScenarios().find(x=>x.id===id);if(!x||role==='조교'||!scope().some(s=>s.id===id))return;modal(`<span class="eyebrow">FOLLOW-UP · 가상 상황</span><h1>${esc(S(id).name)} 학생 챙기기</h1><p>${x.since} · ${esc(S(id).teacher)} 담당</p><div class="notice"><b>확인이 필요한 이유</b><br>${esc(x.reason)}</div><h2 style="margin-top:24px">다음 행동</h2><p>${esc(x.next)}</p><p>다음 확인 ${x.due} · ${badge(x.state)}</p><p class="note">확인 완료는 후속 확인 업무의 완료이며, 학생의 문제가 해결됐다는 판정은 아닙니다.</p><div class="row wrap"><button data-action="care-state" data-id="${id}" data-state="교사 확인 중">내가 확인할게요</button><button class="primary" data-action="care-state" data-id="${id}" data-state="확인 완료">후속 확인 완료</button><button data-action="student" data-id="${id}">학습 기록 보기</button></div>`);}
function consultation(id){if(role==='조교'||!scope().some(s=>s.id===id))return;const es=db.events.filter(e=>e.student===id&&e.visibility==='REPORTABLE');const groups=[['좋아진 점',['잘함','개선']],['최근 어려움',['어려움','반복']],['학원에서 도운 내용',['지도함','나머지 지정','완료']]];modal(`<span class="eyebrow">CONSULTATION NOTES</span><h1>${esc(S(id).name)} 상담 준비</h1><p class="note">공유 가능 기록만 분류한 초안입니다. 원인·퇴원 가능성은 추정하지 않습니다.</p>${groups.map(([title,types])=>{const rows=es.filter(e=>types.includes(e.type)).slice(-2);return `<section class="consult-block"><h2>${title}</h2>${rows.map(e=>`<p>${esc(uiText(e.text))}</p><details><summary>근거 기록 보기</summary><p class="note">${e.date.slice(0,10)} · ${esc(e.actor)} · ${esc(e.area)}</p></details>`).join('')||'<p class="note">공유 가능한 근거가 아직 없습니다.</p>'}</section>`}).join('')}<div class="notice"><b>상담에서 확인할 질문</b><br>최근 집에서 학습할 때 어려워하는 부분이 있나요?<br>다음 수업에서 어떤 도움을 주면 좋을지 함께 정해보세요.</div><button class="primary full-width" data-action="student-report" data-id="${id}">월말리포트에서 정리하기 →</button>`,true);}
function assistantBriefing(){const ids=new Set(db.tasks.filter(t=>t.open).map(t=>t.student)),events=db.events.filter(e=>ids.has(e.student)&&e.date>'2026-09-28T23:59:59').slice(-5).reverse();return `<div class="workspace-banner"><div><span class="eyebrow">WELCOME BACK</span><h2>지난 근무 이후, 이것만 확인하세요.</h2><p>지난 근무 9/28 → 오늘 10/01 · 가상 근무 일정 · 현재 관리 대상 학생 기준</p></div>${badge(db.experience?.briefed?'인계 확인함':'인계 확인 전',db.experience?.briefed?'':'warn')}</div><details class="briefing panel" ${db.experience?.briefed?'':'open'}><summary>담당 학생의 최근 변화 ${events.length}건 · 최대 5건</summary>${events.map(e=>`<div class="item"><div class="grow"><b>${esc(S(e.student).name)}</b><p>${esc(uiText(e.text))}</p><small>${e.date.slice(5,10)} · ${esc(e.actor)}</small></div><button class="small" data-action="task-guide" data-id="${db.tasks.find(t=>t.student===e.student&&t.open).id}">오늘 할 일</button></div>`).join('')||'<p class="note">지난 근무 이후 새 기록이 없습니다.</p>'}<button class="full-width" data-action="briefed">인계 확인했어요 · 접기</button></details>`;}
function taskGuide(id){const t=db.tasks.find(t=>t.id===id);if(!t)return;const s=S(t.student);modal(`<span class="eyebrow">TODAY’S INSTRUCTIONS</span><h1>${esc(s.name)} · 오늘의 작업 지시서</h1><p>${esc(s.class)} · 담당 ${esc(s.teacher)}</p><dl class="instruction-list"><dt>지금 할 일</dt><dd>${esc(t.primaryDone?t.secondary:t.primary)}</dd><dt>지난 진행</dt><dd>${t.primaryDone?(G.optionalPending(t)?'필수 과제 완료 · 선택 복습 잔여':!G.requiresSecondary(t)?'필수 과제 완료':t.secondaryDone?'필수·추가 과제 완료':'기본 과제 완료 · 필수 추가 과제 확인 필요'):'기본 과제 완료 기록 없음'} · ${t.status}</dd><dt>완료 기준</dt><dd>${!t.open?'필수 과제 완료 상태 · 남은 선택 복습은 별도 처리':t.vocab&&!t.primaryDone?`${db.settings.total}문항 중 ${Math.ceil(db.settings.total*db.settings.threshold/100)}개 이상 정답`:'지정 범위 전체 완료 확인'}</dd><dt>다음 순서</dt><dd>${G.requiresSecondary(t)?(t.primaryDone?'필수 추가 과제까지 마치면 최종 완료':esc(t.secondary)+'까지 필수로 확인'):'기본 과제 완료 시 필수 완료 · 추가 복습은 선택'}</dd><dt>지도 방법</dt><dd>먼저 혼자 풀게 하고, 막힌 문항을 함께 확인해 주세요. <small>(체험용 예시)</small></dd><dt>시간·질문</dt><dd>17:50 마무리 확인 · 질문은 ${esc(s.teacher)}에게 <small>(모의 일정)</small></dd></dl><div class="notice">실제 처리 결과는 운영보드에서 저장합니다. 채점 체험은 별도의 5문항 예시입니다.</div><div class="row wrap" style="margin-top:18px"><button class="primary" data-action="close">지시 확인 · 운영보드로</button><button data-action="grade-demo" data-id="${id}">객관식 채점 체험</button></div>`,true);}
function gradeDemo(id){if(!db.tasks.some(t=>t.id===id))return;modal(`<span class="eyebrow">GRADING PREVIEW</span><h1>5문항 채점 체험</h1><p>예시 정답: ① ③ ② ④ ① · 답을 선택하면 채점할 수 있습니다.</p><div class="grade-inputs">${[1,2,3,4,5].map(n=>`<label>${n}번<select id="answer-${n}"><option value="">미입력</option>${options(['1','2','3','4'],'')}</select></label>`).join('')}</div><div id="grade-result" role="status" class="notice">모든 답을 입력해 주세요.</div><button class="primary full-width" data-action="grade-check">채점하기</button><p class="note">이 결과는 학생 기록이나 30문항 재시험에 저장되지 않습니다. 시험지 촬영·OCR은 아직 연결 전입니다.</p>`);}
function experienceAction(b){const a=b.dataset.action,id=Number(b.dataset.id);
 if(a==='care-detail')careDetail(id);
 else if(a==='care-state'){if(role==='조교'||!scope().some(s=>s.id===id)||!careScenarios().some(x=>x.id===id)||!['교사 확인 중','확인 완료'].includes(b.dataset.state))return true;db.experience??={};db.experience.care??={};db.experience.care[id]={state:b.dataset.state};if(save()){render();careDetail(id);}}
 else if(a==='consult')consultation(Number($('consultStudent').value));
 else if(a==='teacher-care'){const list=careScenarios().filter(x=>S(x.id).teacher===b.dataset.name&&filtered().some(s=>s.id===x.id));modal(`<h1>${esc(b.dataset.name)} · 후속 관리</h1><p class="note">가상 확인 업무 · 근무 태도나 교사 평가 점수가 아닙니다.</p>${careRows(list)}`);}
 else if(a==='enrollment')modal('<h1>9월 등록·퇴원 내역</h1><p class="note">UI 체험용 별도 가상 명부 · 실제 학생 명부와 연동 전</p><div class="retention-equation"><span><b>4명</b>신규 등록</span><span><b>2명</b>퇴원</span><span><b>+2명</b>순증</span></div><p>등록: 김민수 · 오시우 · 오예준 · 김태윤</p><p>퇴원: 가상학생 A — 이사 / 가상학생 B — 시간표 변경</p><div class="notice">퇴원 사유를 학습 문제나 담당교사 책임으로 자동 해석하지 않습니다.</div>');
 else if(a==='briefed'){db.experience??={};db.experience.briefed=true;if(save())render();}
 else if(a==='task-guide')taskGuide(id);
 else if(a==='grade-demo')gradeDemo(id);
 else if(a==='grade-check'){const answers=[1,2,3,4,5].map(n=>$('answer-'+n).value),key=['1','3','2','4','1'];if(answers.some(x=>!key.includes(x))){$('grade-result').textContent='5문항의 답을 모두 선택해 주세요.';return true;}const wrong=answers.flatMap((x,i)=>x!==key[i]?[i+1]:[]);$('grade-result').textContent=`${5-wrong.length}/5 정답 · ${wrong.length?'다시 볼 문항: '+wrong.join(', '):'모두 맞았습니다.'} · 체험 결과, 저장 안 됨`;}
 else return false;return true;
}

function dashboard(){
 const ss=filtered(),ids=ss.map(s=>s.id),cs=db.cases.filter(c=>ids.includes(c.student)),ts=db.tasks.filter(t=>ids.includes(t.student)),es=evs(ids);
 const incomplete=ts.filter(t=>t.status==='미완료'),review=ts.filter(t=>t.notification==='검토 필요');
 const focus=[...new Set([...incomplete.map(t=>t.student),...cs.filter(c=>c.status==='OPEN').map(c=>c.student)])];
 return directorOverview()+`<details class="secondary-overview"><summary>학습·반별 상세 현황 펼치기</summary>`+heading('지금 필요한 확인부터','미완료 과제와 학습 이슈를 확인하고, 다음 지도로 이어가세요.',`<button class="primary" data-page="reports">월말리포트 보기 ↗</button>`)
 +`<div class="action-strip"><div><span class="eyebrow">NEXT ACTION</span><h2>${incomplete.length?`이월 과제 ${incomplete.length}건을 확인해 주세요`:'이월 과제 없이 관리되고 있어요'}</h2><p>과제 결과와 학부모 안내를 먼저 확인할 수 있습니다.</p></div><div class="row wrap"><button data-page="board">운영보드 →</button><button class="primary" data-page="notifications">알림 검토 ${review.length}건 →</button></div></div>`
 +`<div class="section-heading"><h2>학원 현황</h2><span class="note">현재 상태 · 아래 학생 필터 적용</span></div>`+filterBar()
 +stats([['재원 학생',ss.length,'명','선택한 교사 · 반 · 학교 기준'],['진행 중 Case',cs.filter(c=>c.status!=='CLOSED').length,'건','관찰과 개입을 이어가는 중'],['나머지 대상',new Set(ts.map(t=>t.student)).size,'명',`완료 포함 · 배정 과제 ${ts.length}건`],['미완료 과제',ts.filter(t=>t.open).length,'건','진행 중 과제와 이월 과제 포함']])
 +`<div class="grid priority-grid"><section class="panel"><div class="section-heading"><h2>먼저 확인할 학생</h2>${badge(focus.length+'명','warn')}</div><p class="note">미완료 귀가 학생 → 미해결 학습 이슈 순서 · 위험도 점수가 아닙니다.</p>${focus.slice(0,6).map(id=>{const student=S(id),task=incomplete.find(t=>t.student===id),c=cs.find(c=>c.student===id&&c.status==='OPEN');return `<div class="item">${avatar(student)}<div class="grow">${link(student)}<p>${esc(student.class)} · ${task?'이월 과제: '+esc(task.primaryDone?task.secondary:task.primary):esc(c.title)}</p></div>${badge(task?'과제 이월':'학습 확인',task?'red':'warn')}<button class="small" data-action="student" data-id="${id}">기록 보기</button></div>`}).join('')||'<div class="empty">현재 조건에서 우선 확인할 학생이 없습니다.</div>'}</section><section class="panel"><div class="section-heading"><h2>반별 현황 · 현재</h2><span class="note">기록 화면으로 바로 이동</span></div><div class="table-wrap"><table><thead><tr><th>반 / 담임</th><th>학생</th><th>미완료</th><th></th></tr></thead><tbody>${[...new Set(ss.map(x=>x.class))].map(cl=>{const members=ss.filter(x=>x.class===cl);return `<tr><td><b>${esc(cl)}</b><small class="cell-sub">${esc(members[0].teacher)}</small></td><td>${members.length}명</td><td>${ts.filter(t=>members.some(x=>x.id===t.student)&&t.open).length}건</td><td><button class="small" data-action="class" data-id="${cl}">반 수업 기록 →</button></td></tr>`}).join('')||'<tr><td colspan="4">선택 조건에 맞는 반이 없습니다.</td></tr>'}</tbody></table></div></section></div>
 <div class="section-heading"><div><h2>기록으로 살펴보기</h2><span class="note">기간 필터는 학습 기록에만 적용됩니다. 과제·Case는 현재 상태입니다.</span></div></div>
 <div class="filters"><label>기록 시작일<input type="date" data-filter="from" value="${filters.from||''}"></label><label>기록 종료일<input type="date" data-filter="to" value="${filters.to||''}"></label><label>Event 유형<select data-filter="type"><option value="">전체 기록</option>${options([...new Set(db.events.map(e=>e.type))],filters.type)}</select></label><span class="note">학습 기록 · 선택 기간 ${es.length}건</span></div>`+analytics(ids,es)+'</details>';
}
function home(){
 const ids=scope().map(s=>s.id),classes=[...new Set(scope().map(s=>s.class))].filter(cl=>cl.endsWith('B')),issues=db.cases.filter(c=>ids.includes(c.student)&&c.status!=='CLOSED');
 return teacherOverview()+heading('오늘 수업을 준비해 볼까요?','확인할 학생을 살펴보고, 반을 선택해 기록을 시작하세요.',`<button class="primary" data-page="session">수업 기록 시작 →</button>`)
 +`<div class="section-heading"><h2>오늘 수업</h2><span class="note">목요일 · 데모 시간표</span></div><div class="class-schedule">${classes.map((cl,i)=>`<button class="class-tile" data-action="class" data-id="${cl}"><span class="eyebrow">${15+i}:00 · ${scope().filter(s=>s.class===cl).length}명</span><strong>${cl}</strong><span>Reading Unit 8 / Essay 의견 쓰기</span><b>학생 확인하고 기록하기 →</b></button>`).join('')}</div>
 <div class="grid"><section class="panel"><div class="section-heading"><h2>수업 전에 확인할 학생</h2>${badge(issues.length+'건','warn')}</div>${issues.map(c=>`<div class="item">${avatar(S(c.student))}<div class="grow">${link(S(c.student))}<p>${esc(c.title)} · ${esc(c.change)}</p></div><button class="small" data-action="quick-record" data-id="${c.student}" data-kind="event">관찰 기록</button></div>`).join('')||'<div class="empty">확인할 학습 이슈가 없습니다.</div>'}</section><section class="panel"><h2>조교가 이어 남긴 기록</h2><p class="note">최근 나머지 결과를 다음 수업에 활용하세요.</p>${db.events.filter(e=>ids.includes(e.student)&&e.area==='나머지').slice(-5).reverse().map(e=>`<div class="item"><div class="grow">${link(S(e.student))}<p>${esc(uiText(e.text))}</p><small>${e.date.slice(5,10)} · ${esc(e.actor)}</small></div></div>`).join('')||'<div class="empty">운영보드에서 결과를 처리하면 표시됩니다.</div>'}<button class="full-width" data-page="students">담당 학생 전체 보기 →</button></section></div>`;
}
// Drafts are kept separately from committed records, including across in-app navigation.
const observationTags={independent:{type:'잘함',text:'도움 없이 스스로 수행함'},help:{type:'어려움',text:'추가 설명 후에도 수행에 어려움이 있음'},improved:{type:'개선',text:'이전 도움 없이 같은 유형을 스스로 해결함'}};
const rosterDrafts={},rosterFailures={};let assignmentSourceLinks={},observationActive=false,observationDirty=false;
function markObservation(t){if(observationActive&&['memo','eventType','area','visibility','observationTag'].includes(t.id)){observationDirty=true;const status=$('observation-save-state');if(status)status.textContent='작성 중 · 아직 저장되지 않았습니다';}}
function discardObservation(){if(!observationDirty)return true;if(!confirm('저장하지 않은 관찰 내용이 있습니다. 내용을 버리고 이동할까요?'))return false;observationDirty=false;return true;}
function scoreEntryState(id){
 const raw=String(rosterDraft()[id]??'').trim();
 if(raw){if(!/^\d+$/.test(raw)||Number(raw)>db.settings.total)return {kind:'error',text:`0~${db.settings.total} 범위의 정수를 입력하세요`};return {kind:'pending',text:(G.assessment(Number(raw),db.settings.total,db.settings.threshold).pass?'PASS':'FAIL')+' 예상 · 미저장'};}
 const last=db.events.filter(e=>e.student===id&&e.type==='시험'&&e.date.startsWith(G.TODAY)).at(-1);
 return last?{kind:'saved',text:`저장됨 · ${last.correct}/${last.total} · ${last.pass?'PASS':'FAIL'}`}:{kind:'empty',text:'미입력'};
}
function scoreEntrySummary(){const ids=rosterMembers().filter(s=>String(rosterDraft()[s.id]??'').trim()!=='').map(s=>s.id),errors=ids.filter(id=>scoreEntryState(id).kind==='error').length;return ids.length?`${ids.length}명 입력 · 미저장${errors?' · 오류 '+errors+'명':''}`:'입력 대기 · 빈칸은 저장하지 않습니다';}
function updateScoreEntry(id){const state=scoreEntryState(id),label=$('score-state-'+id),input=$('score-input-'+id);if(label){label.textContent=state.text;label.dataset.state=state.kind;}input?.setAttribute?.('aria-invalid',String(state.kind==='error'));const summary=$('score-entry-summary');if(summary)summary.textContent=scoreEntrySummary();}
function rosterKey(){return actor()+'|'+className;}
function rosterDraft(){return rosterDrafts[rosterKey()]??={};}
function rosterMembers(){return scope().filter(s=>s.class===className);}
function captureRosterScore(t){if(role==='조교'||page!=='session'||!rosterMembers().some(s=>s.id===Number(t.dataset.rosterScore)))return;rosterDraft()[t.dataset.rosterScore]=t.value;updateScoreEntry(Number(t.dataset.rosterScore));}
function openRosterFailures(){const pending=rosterFailures[rosterKey()]||{};const ids=Object.keys(pending).map(Number).filter(id=>rosterMembers().some(s=>s.id===id)&&db.events.some(e=>e.id===pending[id]));if(!ids.length)return toast('연결할 FAIL 기록이 없습니다.');selected=new Set(ids);render();form('assign',Object.fromEntries(ids.map(id=>[id,pending[id]])));}
function saveRosterScores(){
 if(role==='조교'||page!=='session')return;
 const draft=rosterDraft(),rows=rosterMembers().filter(s=>String(draft[s.id]??'').trim()!=='');
 if(!rows.length)return toast('입력한 점수가 없습니다. 빈칸은 저장하지 않습니다.');
 let assessments;
 try{assessments=rows.map(s=>{const raw=String(draft[s.id]).trim();if(!/^\d+$/.test(raw))throw Error(s.name+' 학생: 정수 정답수를 입력해 주세요.');try{return {student:s.id,...G.assessment(Number(raw),db.settings.total,db.settings.threshold)};}catch(err){throw Error(s.name+' 학생: '+err.message)}});}
 catch(err){return toast(err.message);}
 const failed={};
 assessments.forEach(a=>{const e=G.event(db,a.student,'시험','Vocabulary',`단어 본시험 ${a.correct}/${a.total} · ${a.pass?'PASS':'FAIL'}`,actor(),'REPORTABLE',a);if(!a.pass)failed[a.student]=e.id;});
 if(!save())return;
 rosterDrafts[rosterKey()]={};rosterFailures[rosterKey()]=failed;selected.clear();render();
 if(Object.keys(failed).length){openRosterFailures();toast(`${assessments.length}명 점수 저장 · FAIL 학생만 나머지 지정을 제안합니다.`);}else toast(`${assessments.length}명 점수를 저장했습니다.`);
}

function finishSession(){
 if(role==='조교'||page!=='session')return;
 if(observationDirty)return toast('작성 중인 관찰을 저장하거나 취소한 뒤 마감해 주세요.');
 if(Object.values(rosterDraft()).some(v=>String(v).trim()!==''))return toast('저장하지 않은 점수가 있습니다. 점수를 저장하거나 입력을 비운 뒤 마감해 주세요.');
 const key=G.TODAY+'|'+rosterKey();
 if(db.lessons?.some(x=>x.key===key))return toast('오늘 이 반의 수업은 이미 마감했습니다.');
 db.lessons??=[];db.lessons.push({key,date:G.TODAY,class:className,actor:actor(),note:'특이사항 없음',recordedAt:new Date().toISOString()});
 if(!save())return;selected.clear();page='home';render();toast('특이사항 없음으로 수업 마감을 저장했습니다.');
}
function session(){
 const classes=[...new Set(scope().map(s=>s.class))];if(!classes.includes(className))className=classes[0];const students=scope().filter(s=>s.class===className);
 return heading('수업 기록','점수를 입력하고 저장하세요. 관찰은 필요한 학생만 선택해 기록합니다.',`<label>수업 반<select id="className" aria-label="수업 반">${options(classes,className)}</select></label>`)
 +`<section class="entry-workflow" aria-label="수업 기록 순서"><div><b>학생별 점수 입력</b><span>Enter 다음 학생 · Shift + Enter 이전 학생</span></div><div><b>점수 저장</b><span>FAIL 학생은 나머지 지정으로 연결</span></div><div><b>필요한 관찰 기록</b><span>학생 선택 후 빠른 태그 또는 메모</span></div></section><section class="panel roster-panel"><div class="section-heading"><div><h2>${className} ${badge(students.length+'명')}</h2><span class="note">Reading Unit 8 · 문장 구조와 중심 내용</span></div><button class="small" data-action="select-all">전체 선택 / 해제</button></div><div class="table-wrap"><table class="roster"><thead><tr><th>선택</th><th>학생</th><th>정답수 / ${db.settings.total}</th><th>최근 기록</th><th>관리 상태</th><th>바로 기록</th></tr></thead><tbody>${students.map(student=>{const event=db.events.filter(e=>e.student===student.id).slice(-1)[0],issue=db.cases.some(c=>c.student===student.id&&c.status!=='CLOSED');return `<tr class="${selected.has(student.id)?'selected-row':''}"><td><input type="checkbox" aria-label="${student.name} 선택" data-select="${student.id}" ${selected.has(student.id)?'checked':''}></td><td><div class="row">${avatar(student)}<div>${link(student)}<small class="cell-sub">${student.school} ${student.grade}</small></div></div></td><td><input id="score-input-${student.id}" aria-describedby="score-state-${student.id}" aria-invalid="${scoreEntryState(student.id).kind==='error'}" class="roster-score" type="number" min="0" max="${db.settings.total}" step="1" inputmode="numeric" aria-label="${esc(student.name)} 정답수" data-roster-score="${student.id}" value="${esc(rosterDraft()[student.id]??'')}" placeholder="미입력"><small class="score-state" id="score-state-${student.id}" data-state="${scoreEntryState(student.id).kind}">${esc(scoreEntryState(student.id).text)}</small></td><td class="record-cell">${esc(uiText(event?.text||'기록 없음'))}</td><td>${badge(issue?'학습 이슈':'진행 이슈 없음',issue?'warn':'gray')}</td><td><div class="row row-actions"><button class="small" data-action="quick-record" data-kind="event" data-id="${student.id}">관찰</button><button class="small" data-action="quick-record" data-kind="exam" data-id="${student.id}">시험</button><button class="small" data-action="quick-record" data-kind="assign" data-id="${student.id}">나머지</button></div></td></tr>`}).join('')}</tbody></table></div></section>
 <section class="panel score-toolbar"><div><b id="score-entry-summary" role="status">${scoreEntrySummary()}</b><p class="note">체크박스 선택과 관계없이 입력한 점수를 저장합니다. 빈칸은 미입력, 0은 0점입니다.<br>저장 전 입력은 화면 이동 시 유지되지만 새로고침하면 사라집니다.</p></div><div class="row wrap"><button class="primary" data-action="roster-save">입력한 점수 저장</button><button data-action="roster-fails">최근 FAIL 학생 나머지 지정</button></div></section><div class="selection row between wrap"><div><b>${selected.size}명 선택</b><span class="selection-help">${selected.size?'선택한 학생에게 같은 내용을 기록합니다.':'명단에서 학생을 선택해 주세요.'}</span></div><div class="row wrap"><button data-action="event" ${selected.size?'':'disabled'}>관찰 기록</button><button data-action="exam" ${selected.size?'':'disabled'}>단어시험</button><button class="primary" data-action="assign" ${selected.size?'':'disabled'}>나머지 지정</button></div></div><div class="session-footer"><button class="text-button" data-action="end">특이사항 없음 · 수업 마감</button><span class="note">마감은 데모 날짜·반·기록자별로 저장됩니다. 학생 관찰을 자동 생성하지 않습니다.</span></div>`;
}
function taskCard(t){const st=t.status,s=S(t.student),mins=t.started?Math.floor((Date.now()-t.started)/60000):0;return `<article class="task" data-state="${t.status}" data-student="${s.id}" data-tone="${(s.id-1)%6}" aria-label="${esc(s.name)} · ${esc(t.status)} 과제"><header class="task-cover"><span class="task-monogram" aria-hidden="true">${esc(s.name.slice(-2))}</span><div class="task-identity"><b>${role==='조교'?esc(s.name):link(s)}</b><small>${esc(s.class)} · ${esc(s.teacher)}</small></div><span class="task-state-label">${t.open&&st==='미완료'?'미완료 · 미해결':esc(t.status)}</span></header><div class="task-content"><p>${esc(t.reason)}</p><button class="guide-button" data-action="task-guide" data-id="${t.id}">지시서 크게 보기 ↗</button><div class="note">${t.primaryDone?(G.requiresSecondary(t)?'필수 추가 과제':'선택 복습'):'기본 과제'}${!G.requiresSecondary(t)?' · 추가 복습은 선택':''}</div><p><b>${esc(t.primaryDone?t.secondary:t.primary)}</b></p>${t.primaryDone?badge('기본 과제 완료'):''}<div class="time">${t.started?`${new Date(t.started).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})} 시작 · ${mins}분 경과 ${mins>=45&&t.open?'⚠ 셔틀 전 확인':''}`:'입실 대기'}</div>${st==='완료'?`${badge(G.requiresSecondary(t)?'모든 과제 완료':'필수 과제 완료')}${G.optionalPending(t)?`<p class="note">선택 복습 잔여 · 미완료 집계 제외</p><button class="small" data-action="task" data-id="${t.id}" data-op="복습완료">선택 복습 완료 기록</button>`:(!G.requiresSecondary(t)&&t.secondaryDone?badge('선택 복습 완료'):'')}`:st==='미완료'?`<p class="note">다음 등원 시 이어서 진행<br>학부모 알림: ${t.notification}</p><button class="small" data-action="task" data-id="${t.id}" data-op="시작">다시 시작</button>`:`${st==='대기'?`<button class="primary small" data-action="task" data-id="${t.id}" data-op="시작">입실 · 시작</button>`:`<label class="task-field">도움 정도<select aria-label="${s.name} 도움 정도" data-help="${t.id}">${observationOptions(['혼자 수행','1~2회 도움','지속적 도움'],t.help)}</select></label><label class="task-field">진행 상태<select aria-label="${s.name} 진행 상태" data-progress="${t.id}">${observationOptions(['원활','반복 독촉','거의 진행 못함'],t.progress)}</select></label>${t.vocab&&!t.primaryDone?`<div class="row" style="margin-top:8px"><input id="score-${t.id}" type="number" min="0" max="${db.settings.total}" placeholder="정답수" aria-label="${s.name} 정답수"><small>/ ${db.settings.total}</small></div>`:''}<button class="primary small" data-action="task" data-id="${t.id}" data-op="결과">${t.primaryDone?'추가 과제 완료':t.vocab?'재시험 결과 저장':'기본 과제 완료'}</button>${st==='학습중'?`<button class="small" data-action="task" data-id="${t.id}" data-op="확인">확인대기</button>`:''}`}<button class="small text-button danger-link" data-action="task" data-id="${t.id}" data-op="귀가">미완료 귀가</button>`}</div></article>`}
function board(){
 const active=db.tasks.filter(t=>t.status!=='완료'),done=db.tasks.filter(t=>t.status==='완료');
 return assistantBriefing()+heading('나머지 학습실','학생별 카드를 살펴보고 지시서를 크게 열어보세요. 확인대기부터 순서대로 표시합니다.',badge('모의 셔틀 18:00','gray'))
 +`<div class="board-summary"><span><b>${new Set(active.map(t=>t.student)).size}</b>명 관리 중</span><span><b>${active.filter(t=>t.status==='확인대기').length}</b>건 확인대기</span><span><b>${done.length}</b>건 완료</span><small>미완료 과제는 귀가 후에도 유지됩니다.</small></div><div class="board">${['확인대기','대기','학습중','미완료'].map(st=>`<section class="column" data-state="${st}"><h3><span class="status-dot"></span>${st==='미완료'?'미완료 · 이월':st}<span class="badge gray">${active.filter(t=>t.status===st).length}건</span></h3><div class="student-gallery">${active.filter(t=>t.status===st).map(taskCard).join('')||'<div class="empty">대상 없음</div>'}</div></section>`).join('')}</div><details class="completed-tasks"><summary>완료한 과제 <b>${done.length}건</b><span>펼쳐보기</span></summary><div class="cards">${done.map(taskCard).join('')||'<div class="empty">완료한 과제가 없습니다.</div>'}</div></details>`;
}
function students(){return heading('학생 360','담임·원어민·조교의 기록을 한 학생의 이야기로 연결합니다.')+filterBar()+`<div class="cards">${filtered().map(s=>`<article class="student-card"><div class="row">${avatar(s)}<div>${link(s)}<p style="margin:4px 0">${s.school} · ${s.grade}</p></div></div><p>${s.class} · 담임 ${s.teacher}<br>Essay / Speaking · ${s.native}</p><div class="row">${badge(db.events.filter(e=>e.student===s.id).length+'개 기록')}${db.tasks.some(t=>t.student===s.id&&t.open)?badge('미완료 과제','warn'):''}</div></article>`).join('')||'<div class="empty">조건에 맞는 학생이 없습니다.</div>'}</div>`}
function studentModal(id){const s=S(id);if(!scope().some(x=>x.id===s.id))return;studentId=s.id;const es=db.events.filter(e=>e.student===s.id).sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id);modal(`<div class="row">${avatar(s)}<div><h1>${s.name}</h1><span class="muted">${s.school} ${s.grade} · ${s.class}</span></div></div><p class="note">담임 ${s.teacher} · 원어민 ${s.native} · 두 교사의 기록을 통합합니다.</p><div class="row">${badge(es.length+'개 통합 기록')}${badge(db.tasks.filter(t=>t.student===s.id&&t.open).length+'개 미완료 과제','warn')}</div><div class="timeline">${es.map(e=>`<article><small>${e.date.slice(0,10)} · ${esc(e.actor)}</small><p>${badge(e.type)} <b>${esc(e.area)}</b></p><p>${esc(uiText(e.text))}</p>${badge(e.visibility,e.visibility==='REPORTABLE'?'':'warn')}</article>`).join('')}</div><button class="primary" data-action="student-report" data-id="${s.id}">이 학생 월말리포트 보기 →</button>`,true)}
function signals(){return scope().flatMap(s=>{const es=db.events.filter(e=>e.student===s.id);let out=[];if(es.filter(e=>e.type==='재시험'&&e.pass&&e.elapsed!==null&&e.elapsed<=10).length>=2&&es.filter(e=>e.type==='시험'&&!e.pass).length>=2)out.push({student:s.id,title:'사전 준비습관 점검'});if(es.filter(e=>e.type==='과제'&&e.text.includes('미완료')&&e.date.slice(0,10)>='2026-09-04').length>=3)out.push({student:s.id,title:'과제습관 관리'});if(es.filter(e=>e.type==='어려움'||e.type==='반복').length>=2)out.push({student:s.id,title:'반복 학습 어려움 확인'});return out})}
function cases(){return heading('발견에서 변화까지','학습 이슈를 개입과 변화의 근거로 이어갑니다.')+`<div class="notice">규칙 기반 후보 ${signals().length}건 · 반복 어려움 2회 / 4주 내 과제 미완료 3회 / 본시험 FAIL + 10분 내 재시험 PASS 반복을 확인합니다.</div>${signals().map((x,i)=>`<div class="item"><div class="grow">${S(x.student).name} · ${x.title}</div><button data-action="case-create" data-id="${i}">Case로 등록</button></div>`).join('')}<div class="cards">${db.cases.filter(c=>scope().some(s=>s.id===c.student)).map(c=>`<section class="panel"><div class="row between">${link(S(c.student))}${badge(c.status)}</div><h2 style="margin-top:20px">${esc(c.title)}</h2><p class="note">발견</p><p>${esc(c.discovery)}</p><p class="note">학원의 개입</p><p>${esc(c.intervention)}</p><p class="note">변화 / 다음 확인</p><p>${esc(c.change)}</p><select data-case="${c.id}" aria-label="${S(c.student).name} Case 상태">${options(['OPEN','MONITORING','IMPROVING','CLOSED'],c.status)}</select></section>`).join('')}</div>`}
const sections=['이번 달 학습 요약','잘하고 있는 점','현재 관리 포인트','학원의 대응','Essay & Speaking','나머지 학습','다음 달 지도계획'];
function draft(id,m){const es=G.reportEvents(db,id,m),cs=db.cases.filter(c=>c.student===id&&c.visibility==='REPORTABLE');const lines=arr=>arr.map(e=>`${e.date.slice(5,10)} · ${e.area}: ${uiText(e.text)}`).join('\n')||'이 기간에 확인된 공유용 기록이 없습니다.';return [`${S(id).name} 학생의 ${m} 공유 가능 기록 ${es.length}건을 바탕으로 정리했습니다.\n`+lines(es.filter(e=>['시험','과제'].includes(e.type))),lines(es.filter(e=>['잘함','개선'].includes(e.type))),lines(es.filter(e=>['어려움','반복'].includes(e.type))),lines(es.filter(e=>['지도함','나머지 지정'].includes(e.type))),lines(es.filter(e=>['Essay','Speaking'].includes(e.area))),lines(es.filter(e=>e.area==='나머지'||e.type==='재시험')),cs.length?cs.map(c=>`[현재 Case: ${c.title}] ${c.intervention} → ${c.change}`).join('\n'):'다음 수업의 관찰을 바탕으로 지도계획을 작성해 주세요.'];}
function reports(){if(!scope().some(s=>s.id===studentId))studentId=scope()[0].id;const k=studentId+'-'+month,r=db.reports[k],body=r?.body||draft(studentId,month);return heading('한 달의 기록, 한 학생의 성장','확인된 근거를 골라 학부모와 공유할 이야기로 정리합니다.')+`<div class="filters"><select id="reportStudent" aria-label="리포트 학생">${scope().map(s=>`<option value="${s.id}" ${s.id===studentId?'selected':''}>${s.name} · ${s.class}</option>`).join('')}</select><input type="month" id="reportMonth" aria-label="리포트 월" value="${month}"><button data-action="report-generate">근거 기반 초안 다시 만들기</button>${badge(r?.status||'초안','warn')}</div><p class="note">AI 연결 전의 템플릿 초안입니다. INTERNAL ONLY / NEEDS REVIEW 기록은 제외합니다. Case는 현재 상태이며 다음 지도계획에 참고합니다.</p><article class="report"><header><div class="eyebrow">MONTHLY GROWTH REPORT</div><h1>${S(studentId).name} 학생의 성장 이야기</h1><p class="muted">${month} · ${S(studentId).class} · ${S(studentId).teacher} & James</p>${badge(r?.status==='승인 완료'?'교사 검토 완료':'검토 전 초안','gray')}</header>${sections.map((t,i)=>`<h2>${String(i+1).padStart(2,'0')} &nbsp; ${t}</h2><textarea data-report="${i}" aria-label="${t}">${esc(body[i])}</textarea><div class="print-text">${esc(body[i])}</div>`).join('')}<div class="notice print-hide">내용을 수정하면 승인 상태가 초안으로 돌아갑니다. 사실관계와 표현을 확인한 뒤 승인해 주세요.</div><div class="row wrap print-hide" style="margin-top:20px"><button data-action="report-save">수정본 저장</button><button class="primary" data-action="report-approve">검토 완료 · 승인</button><button data-action="report-print">공유용 인쇄 / PDF</button></div></article>`}
function notifications(){const ts=db.tasks.filter(t=>t.notification&&scope().some(s=>s.id===t.student));return heading('학부모 알림 검토함','미완료 사실과 다음 계획을 확인하고, 검토 후 발송을 체험합니다.')+`<div class="notice">실제 문자·알림은 발송되지 않습니다. 선택 복습 잔여만으로 안내를 만들지 않습니다.</div>${ts.map(t=>`<section class="panel" style="margin-top:16px"><div class="row between"><h2>${esc(S(t.student).name)} · 과제 안내</h2>${badge(t.notification,'warn')}</div>${t.open?`<p>${esc(t.notificationBody||((t.primaryDone?t.secondary:t.primary)+' 미완료 · 다음 등원 이월'))}</p><p>담당교사가 남은 범위와 다음 확인 계획을 검토합니다.</p>`:`<p>필수 과제는 완료되었습니다. ${t.notification==='후속 확인 필요'?'이전에 모의 발송한 안내의 후속 설명이 필요한지 교사가 확인해 주세요.':'이전 미완료 안내는 취소되었으며 발송할 수 없습니다.'}</p><p class="note">이전 사유: ${esc(t.notificationBody||'기존 미완료 과제 안내')}</p>`}<p class="note">${t.reviewedBy?'검토자: '+esc(t.reviewedBy):''} ${t.sentAt?'· 이전 모의 발송: '+new Date(t.sentAt).toLocaleString('ko-KR'):''}</p>${t.notificationHistory?.length?`<details><summary>이전 안내 이력 ${t.notificationHistory.length}건</summary>${t.notificationHistory.map(n=>`<p class="note">${esc(n.status)} · ${esc(n.body)} ${n.sentAt?'· 모의 발송 '+esc(n.sentAt):''}</p>`).join('')}</details>`:''}${t.open&&t.notification==='검토 필요'?`<button data-action="notify-review" data-id="${t.id}">내용 확인 · 승인</button>`:t.open&&t.notification==='승인 완료'?`<button class="primary" data-action="notify-send" data-id="${t.id}">발송 시뮬레이션</button>`:''}</section>`).join('')||'<div class="empty">검토할 알림이 없습니다.</div>'}`}
function settings(){return heading('워크스페이스 설정','테스트 운영 기준과 가상 데이터 구성을 확인합니다.')+`<section class="panel"><h2>단어시험 기준</h2><div class="formgrid"><label>총 문항수<input id="total" type="number" min="1" max="200" value="${db.settings.total}"></label><label>PASS 기준 (%)<input id="threshold" type="number" min="1" max="100" value="${db.settings.threshold}"></label></div><p class="note">현재 기준 ${Math.ceil(db.settings.total*db.settings.threshold/100)}개 이상 정답이면 PASS · 이후 입력할 시험부터 적용</p><button class="primary" data-action="settings-save">기준 저장</button></section><div class="grid"><section class="panel"><h2>가상 운영 구성</h2><p>학생 48명 · 6개 반 · 반별 8명<br>담임교사 3명 + 원어민교사 James<br>모든 학생에 담임 / 원어민 복수 연결</p><p class="note">이 버전은 역할별 화면 체험입니다. 실제 로그인·서버 권한 검증은 DB 연결 단계에서 구현합니다.</p></section><section class="panel"><h2>데모 데이터</h2><p class="muted">처음 상태로 돌아가 같은 흐름을 다시 체험할 수 있습니다.</p><button data-action="reset">데모 데이터 초기화</button><p class="note">추가한 기록과 수정한 리포트가 초기화됩니다.</p></section></div>`}
function modal(body,wide=false){if(!discardObservation())return;observationActive=false;$('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><div class="row between"><span class="eyebrow">이음 · GROWTH WORKSPACE</span><button data-action="close" aria-label="닫기">✕</button></div>${body}</section></div>`;setTimeout(()=>$('overlay').querySelector('input,textarea,select,button')?.focus(),0)}function close(force=false){if(!force&&!discardObservation())return false;$('overlay').innerHTML='';assignmentSourceLinks={};observationActive=false;observationDirty=false;return true;}
function assignmentSources(){return [...selected].map(id=>{const exams=db.events.filter(e=>e.student===id&&e.type==='시험'&&e.pass===false);return `<label class="full">${esc(S(id).name)} · 근거 시험<select id="assignment-source-${id}"><option value="independent" ${assignmentSourceLinks[id]?'':'selected'}>시험 연결 없이 별도 지정</option>${exams.slice().reverse().map(e=>`<option value="${e.id}" ${assignmentSourceLinks[id]===e.id?'selected':''}>${esc(e.date+' · '+e.text)}</option>`).join('')}</select></label>`;}).join('');}
function form(action,sources={}){if(!discardObservation())return;assignmentSourceLinks=sources;if(!selected.size)return toast('학생을 먼저 선택해 주세요.');const who=[...selected].map(id=>S(id).name).join(', ');let body=action==='event'?`<label>관찰<select id="eventType">${options(['잘함','어려움','반복','개선','지도함','과제'],'잘함')}</select></label><label>영역<select id="area">${options(teacher==='James'?['Essay','Speaking']:['Reading','Grammar','Vocabulary','Listening','Essay','Speaking'],'Reading')}</select></label><label class="full">빠른 관찰 태그<select id="observationTag"><option value="">직접 작성</option>${Object.entries(observationTags).map(([key,t])=>`<option value="${key}">${t.text}</option>`).join('')}</select></label><label class="full">추가 메모 (태그 선택 시 생략 가능)<textarea id="memo" placeholder="예: 문장 구조 표시 후 주어·동사를 스스로 구분함"></textarea></label><label class="full">리포트 공개 범위<select id="visibility">${options(['REPORTABLE','INTERNAL ONLY','NEEDS REVIEW'],'REPORTABLE')}</select></label>`:action==='exam'?`<label class="full">정답수 (전체 ${db.settings.total}문항)<input id="correct" type="number" min="0" max="${db.settings.total}" placeholder="예: 24"></label><p class="note full">${Math.ceil(db.settings.total*db.settings.threshold/100)}개 이상 PASS. FAIL이면 나머지 지정을 제안합니다.</p>`:`<label>사유<select id="reason">${options(['단어 FAIL','Reading 과제 미완료','추가 지도'],'단어 FAIL')}</select></label><label>완료조건<span>${db.settings.threshold}% 이상 / 지정 범위 완료</span></label><label class="full">기본 과제<input id="primary" value="Unit 8 단어 재시험"></label><label>추가 과제 기준<select id="secondaryRequired"><option value="optional" selected>선택 복습 (기본)</option><option value="required">필수 추가 과제</option></select></label><p class="note">선택 복습만 남으면 필수 과제 완료로 처리하며, 미완료 귀가 안내를 만들지 않습니다.</p><label class="full">추가 과제 / 선택 복습<input id="secondary" value="누적 단어 오답 10개 복습"></label>`;modal(`<h1>${action==='event'?'빠른 관찰 기록':action==='exam'?'단어시험 결과':'나머지 지정'}</h1><p class="muted">${who} · ${selected.size}명</p><form id="entryForm" data-kind="${action}"><div class="formgrid">${body}${action==='assign'?assignmentSources():''}</div>${action==='event'?'<p id="observation-save-state" class="note" role="status">저장을 누르면 학생 기록에 반영됩니다.</p>':''}<footer><button type="button" data-action="close">취소</button><button class="primary">${action==='assign'?'조교 운영보드로 보내기':'저장'}</button></footer></form>`);observationActive=action==='event';}
function persistReport(status){db.reports[studentId+'-'+month]={body:[...document.querySelectorAll('[data-report]')].map(e=>e.value),status,reviewedBy:status==='승인 완료'?actor():null};return save();}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let a=b.dataset.action,id=Number(b.dataset.id);if(observationDirty&&(a||b.dataset.page)&&!['close','end','retry-save'].includes(a)){if(!discardObservation())return;close(true);}if(b.dataset.page){page=b.dataset.page;selected.clear();render();return}if(!a)return;if(a==='roster-save')return saveRosterScores();if(a==='roster-fails'){if(role==='조교'||page!=='session')return;return openRosterFailures();}if(experienceAction(b))return;if(a==='retry-save'){if(retrySave)retrySave();return}if(a==='close')return close();if(a==='student')return studentModal(id);if(a==='quick-record'){if(!scope().some(s=>s.id===id))return;selected=new Set([id]);render();return form(b.dataset.kind)}if(['event','exam','assign'].includes(a))return form(a);if(a==='clear-filters'){filters={};search=''}if(a==='class'){className=b.dataset.id;page='session';selected.clear()}if(a==='select-all'){let ss=scope().filter(s=>s.class===className);selected=selected.size===ss.length?new Set():new Set(ss.map(s=>s.id))}if(a==='end')return finishSession();if(a==='task'){const t=db.tasks.find(x=>x.id===id),op=b.dataset.op;try{const raw=$('score-'+id)?.value;if(op==='결과'&&t.vocab&&!t.primaryDone&&(raw===''||raw===undefined))return toast('정답수를 입력해 주세요.');for(const field of ['help','progress']){const input=document.querySelector(`[data-${field}="${t.id}"]`);if(input)t[field]=input.value;}G.result(db,t,op,actor(),Number(raw));if(!save())return;toast(op==='복습완료'?'선택 복습 완료를 기록했습니다.':op==='귀가'?(t.open?'과제를 이월하고 학부모 알림 검토를 생성했습니다.':'필수 과제는 이미 완료됐습니다. 미완료 안내를 만들지 않았습니다.'):op==='결과'&&t.primaryDone&&t.open?'기본 과제 완료! 추가 과제를 이어서 진행하세요.':'운영보드와 학생 기록에 반영했습니다.')}catch(err){db=JSON.parse(savedState);return toast(err.message)}}if(a==='student-report'){studentId=id;page='reports';close()}if(a==='case-create'){let x=signals()[id];if(db.cases.some(c=>c.student===x.student&&c.title===x.title&&c.status!=='CLOSED'))return toast('이미 관리 중인 Case입니다.');db.cases.push({id:Date.now(),...x,status:'OPEN',discovery:'반복 기록에서 규칙 기반 탐지',intervention:'담당교사 확인 예정',change:'다음 수업에서 확인',visibility:'NEEDS REVIEW'});if(!save())return;toast('검토 대상 Case로 등록했습니다.')}if(a==='notify-review'){let t=db.tasks.find(t=>t.id===id);if(!t?.open||t.notification!=='검토 필요')return toast('현재 검토할 미완료 안내가 아닙니다.');t.notification='승인 완료';t.reviewedBy=actor();if(!save())return;toast('알림 내용을 승인했습니다.')}if(a==='notify-send'){let t=db.tasks.find(t=>t.id===id);if(!t?.open||t.notification!=='승인 완료')return toast('승인된 미완료 안내만 모의 발송할 수 있습니다.');t.notification='모의 발송 완료';t.sentAt=new Date().toISOString();if(!save())return;toast('발송 시뮬레이션 완료 · 실제 전송되지 않았습니다.')}if(a==='report-save'||a==='report-approve'){if(!persistReport(a==='report-save'?'초안':'승인 완료'))return;toast(a==='report-save'?'수정본을 저장했습니다.':'공유용 리포트를 승인했습니다.')}if(a==='report-generate'){if(!confirm('기존 수정본을 근거 기반 초안으로 교체할까요?'))return;delete db.reports[studentId+'-'+month];if(!save())return;}if(a==='report-print'){if(saveFailed)return toast('저장되지 않은 변경이 있습니다. 먼저 다시 저장해 주세요.',true);if(db.reports[studentId+'-'+month]?.status!=='승인 완료')return toast('교사 검토·승인을 먼저 완료해 주세요.');window.print();return}if(a==='settings-save'){let total=Number($('total').value),threshold=Number($('threshold').value);if(!Number.isInteger(total)||total<1||total>200||threshold<1||threshold>100)return toast('문항수 1~200, 통과율 1~100을 입력해 주세요.');db.settings={total,threshold};if(!save())return;toast('시험 기준을 저장했습니다.')}if(a==='reset'){if(!confirm('추가 기록과 리포트를 지우고 데모를 초기화할까요?'))return;db=G.seed();if(!save())return;selected.clear();toast('초기화했습니다.')}render()});
function handleChange(e){const t=e.target;markObservation(t);if(observationDirty&&['role','teacher','className'].includes(t.id)){const previous=t.id==='role'?role:t.id==='teacher'?teacher:className;if(!discardObservation()){t.value=previous;return;}close(true);}if(t.dataset.rosterScore){captureRosterScore(t);return;}if(t.id==='observationTag'){const tag=observationTags[t.value];if(tag)$('eventType').value=tag.type;return;}if(t.id==='role'){role=t.value;page=role==='원장'?'dashboard':role==='교사'?'home':'board';selected.clear();filters={};search='';close()}if(t.id==='teacher'){teacher=t.value;selected.clear();filters={}}if(t.id==='className'){className=t.value;selected.clear()}if(t.dataset.select){let id=Number(t.dataset.select);t.checked?selected.add(id):selected.delete(id)}if(t.dataset.filter)filters[t.dataset.filter]=t.value;if(t.id==='search')search=t.value;if(t.id==='reportStudent')studentId=Number(t.value);if(t.id==='reportMonth'){if(!t.value)return;month=t.value}if(t.dataset.help||t.dataset.progress){const id=Number(t.dataset.help||t.dataset.progress),task=db.tasks.find(x=>x.id===id);for(const field of ['help','progress']){const input=t.dataset[field]?t:document.querySelector(`[data-${field}="${id}"]`);if(input)task[field]=input.value;}save(()=>handleChange({target:t}));return;}if(t.dataset.case){let c=db.cases.find(c=>c.id===Number(t.dataset.case));c.status=t.value;G.event(db,c.student,'Case 상태 변경','학습관리',`${c.title} → ${c.status}`,actor(),c.visibility);if(!save(()=>handleChange({target:t})))return;}if(t.dataset.report!==undefined){persistReport('초안');return}if(t.closest('#entryForm')){if(t.id==='reason'){$('primary').value=t.value==='단어 FAIL'?'Unit 8 단어 재시험':'Reading p.32~35 완료';$('secondary').value=t.value==='단어 FAIL'?'누적 단어 오답 10개 복습':'핵심 문장 3개 요약'}return}render();}
document.addEventListener('change',handleChange);
document.addEventListener('input',e=>{markObservation(e.target);if(e.target.dataset.rosterScore)captureRosterScore(e.target)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();return;}if(e.isComposing||e.key!=='Enter'||!e.target.dataset.rosterScore||page!=='session'||role==='조교')return;const ids=rosterMembers().map(s=>s.id),index=ids.indexOf(Number(e.target.dataset.rosterScore));if(index<0)return;e.preventDefault();const next=ids[index+(e.shiftKey?-1:1)];if(next!==undefined){$('score-input-'+next)?.focus?.();$('score-input-'+next)?.select?.();}});
window.addEventListener('beforeunload',e=>{if(observationDirty||Object.values(rosterDrafts).some(d=>Object.values(d).some(v=>String(v).trim()!==''))){e.preventDefault();e.returnValue='';}});
document.addEventListener('submit',e=>{if(e.target.id!=='entryForm')return;e.preventDefault();let kind=e.target.dataset.kind;if(kind==='event'){const tag=observationTags[$('observationTag')?.value];let memo=[tag?.text,$('memo').value.trim()].filter(Boolean).join(' · ');if(!memo)return toast('관찰 내용을 입력해 주세요.');selected.forEach(id=>G.event(db,id,$('eventType').value,$('area').value,memo,actor(),$('visibility').value))}if(kind==='exam'){if($('correct').value==='')return toast('정답수를 입력해 주세요.');try{const a=G.assessment(Number($('correct').value),db.settings.total,db.settings.threshold);const sources={};selected.forEach(id=>{const event=G.event(db,id,'시험','Vocabulary',`단어 본시험 ${a.correct}/${a.total} · ${a.pass?'PASS':'FAIL'}`,actor(),'REPORTABLE',a);sources[id]=event.id;});if(!a.pass){if(!save())return;close();toast('FAIL 기록 저장 · 나머지 지정을 제안합니다.');form('assign',sources);return}}catch(err){return toast(err.message)}}if(kind==='assign'){let primary=$('primary').value.trim(),secondary=$('secondary').value.trim();const secondaryRequired=$('secondaryRequired')?.value==='required';if(!primary||(secondaryRequired&&!secondary))return toast('기본 과제와 필수 추가 과제를 입력해 주세요.');const sources={};for(const id of selected){if(!scope().some(s=>s.id===id)||role==='조교')return toast('담당 학생만 지정할 수 있습니다.');const value=$('assignment-source-'+id)?.value||assignmentSourceLinks[id];if(value&&value!=='independent'){const event=db.events.find(e=>e.id===Number(value)&&e.student===id&&e.type==='시험'&&e.pass===false);if(!event)return toast('선택한 근거 시험을 확인해 주세요.');sources[id]=event.id;}}const normalize=value=>String(value??'').trim().replace(/\s+/g,' ');if([...selected].some(id=>sources[id]&&db.tasks.some(t=>t.student===id&&t.sourceAssessmentId===sources[id]&&normalize(t.primary)===normalize(primary)&&normalize(t.secondary)===normalize(secondary)&&t.reason===$('reason').value&&G.requiresSecondary(t)===secondaryRequired)))return toast('같은 시험에 같은 과제가 이미 지정돼 있습니다. 기존 과제를 확인해 주세요.');assignmentSourceLinks=sources;selected.forEach(id=>{db.tasks.push({id:Date.now()+Math.random(),student:id,...(assignmentSourceLinks[id]?{sourceAssessmentId:assignmentSourceLinks[id]}:{}),reason:$('reason').value,primary,secondary,secondaryRequired,vocab:$('reason').value==='단어 FAIL',status:'대기',open:true,started:null,attempt:0});G.event(db,id,'나머지 지정','나머지',primary+(secondary?' · '+(secondaryRequired?'필수 추가 과제: ':'선택 복습: ')+secondary:''),actor())})}if(!save())return;close(true);toast('저장했습니다. 학생 기록과 관련 화면에 반영됩니다.');selected.clear();render()});
window.addEventListener('storage',e=>{if(e.key===KEY){try{db=JSON.parse(e.newValue);savedState=JSON.stringify(db);render()}catch{}}});render();
